ST.xhtml:p:
Tring_CheckStart(CLK := g_bCheckPipeSizeBeforeCuttingStartM);
Tring_CheckEnd(CLK := g_bCheckPipeSizeBeforeCuttingEndM);
IF Tring_CheckStart.Q THEN
  g_bCheckPipeSizeBeforeCuttingStartM := FALSE;
  nCheckState := 10;
END_IF;
IF Tring_CheckEnd.Q THEN
  g_bCheckPipeSizeBeforeCuttingEndM := FALSE;
  nCheckState := 15;

END_IF;
dActualMax := MAX(g_dSquareLenght,g_dSquareWidth)/2.0;(*最大尺寸*)
dActualMin := MIN(g_dSquareLenght,g_dSquareWidth)/2.0; (*最小尺寸*)


R_Trigger0(CLK := g_bFlatNumEnableM);


CASE nCheckState OF
  0:
	nCheckState := 0;
  10:
	IF R_Trigger0.Q THEN
		IF LREAL_TO_INT(g_fFlatNumM) = 1 THEN
			dZAxisCurPos1 := g_fZCoordinate;
		ELSIF LREAL_TO_INT(g_fFlatNumM) = 2 THEN
			dZAxisCurPos2 := g_fZCoordinate;
		END_IF;
		g_bFlatNumEnableM := FALSE;
		IF g_bPlcPauseBuffer THEN
		  nCheckState := 20;
		END_IF;  
    END_IF;
  15:(*根据坐标比较管材尺寸,容许值放宽0.3mm*)
	bAlarmFlag := FALSE;
	IF ABS(dZAxisCurPos1) > ABS(dZAxisCurPos2) THEN
      dCompensate1 := ABS(g_dChuckCenterInZpos)-ABS(dZAxisCurPos1)-1.0;
      dCompensate2 := ABS(g_dChuckCenterInZpos)-ABS(dZAxisCurPos2)-1.0;
    ELSE
      dCompensate1 := ABS(g_dChuckCenterInZpos)-ABS(dZAxisCurPos2)-1.0;
      dCompensate2 := ABS(g_dChuckCenterInZpos)-ABS(dZAxisCurPos1)-1.0;
    END_IF;
    IF NOT (dCompensate1 >= dActualMin-dCheckCompen AND dCompensate1 <= dActualMin+dCheckCompen) THEN
      bAlarmFlag := TRUE;
    END_IF;
    IF NOT (dCompensate2 >= dActualMax-dCheckCompen AND dCompensate2 <= dActualMax+dCheckCompen) THEN
      bAlarmFlag := TRUE;
    END_IF;
    IF bAlarmFlag THEN
      g_bCheckPipeSizeBeforeCuttingAlarm := TRUE;
      g_bZLiftExecute := TRUE;
    ELSE
      g_bCheckPipeSizeBeforeCuttingAlarm := FALSE;
      M.ENABLE[331] := 0;
    END_IF;
    nCheckState := 0;
  20:
	IF g_bPlcStartBuffer THEN
		nCheckState := 10;
	END_IF;

END_CASE;

IF g_bPlcResetBuffer  THEN
 g_bCheckPipeSizeBeforeCuttingStartM := FALSE;
  g_bCheckPipeSizeBeforeCuttingEndM := FALSE;
  nCheckState := 0;
END_IF;
